; di = expected (16 bytes), dx = name ('$' terminated); prints FAIL lines and counts PASS silently
check:
	push dx
	mov si, res
	mov cx, 16
	repe cmpsb
	pop dx
	jne .fail
	inc word [passes]
	ret
.fail:
	inc byte [fails]
	push dx
	mov dx, s_fail
	mov ah, 9
	int 21h
	pop dx
	mov ah, 9
	int 21h
	mov dx, s_nl
	mov ah, 9
	int 21h
	ret

